schema:
CREATE TABLE BOND (
    BOND_ID VARCHAR,
    MOLECULE_ID VARCHAR,
    BOND_TYPE VARCHAR,
    PRIMARY KEY (bond_id),
    FOREIGN KEY (molecule_id) REFERENCES molecule(molecule_id)
);

