CREATE TABLE member AS SELECT 'John' AS first_name, 'Doe' AS last_name, 'Manager' AS position, 28092 AS zip FROM dual UNION ALL SELECT 'Jane' AS first_name, 'Smith' AS last_name, 'Developer' AS position, 28092 AS zip FROM dual;
CREATE TABLE zip_code AS SELECT 28092 AS zip_code, 'Lincolnton' AS city, 'North Carolina' AS state FROM dual;
CREATE TABLE member AS SELECT 'John' AS first_name, 'Doe' AS last_name, 'Manager' AS position, 28092 AS zip FROM dual UNION ALL SELECT 'Jane' AS first_name, 'Smith' AS last_name, 'Developer' AS position, 28092 AS zip FROM dual;
CREATE TABLE zip_code AS SELECT 28092 AS zip_code, 'Lincolnton' AS city, 'North Carolina' AS state FROM dual;

